-- Finance Command Center. Additive only: touches no existing table.
BEGIN;
CREATE TABLE IF NOT EXISTS fin_accounts (id SERIAL PRIMARY KEY, institution VARCHAR(64) NOT NULL, last4 VARCHAR(4) NOT NULL UNIQUE, name VARCHAR(96) NOT NULL, designation VARCHAR(16) NOT NULL DEFAULT 'business', status VARCHAR(16) NOT NULL DEFAULT 'unknown', in_scope BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS fin_import_batches (id SERIAL PRIMARY KEY, filename VARCHAR(200) NOT NULL, kind VARCHAR(24) NOT NULL, sha256 VARCHAR(64) NOT NULL, rows_read INTEGER NOT NULL DEFAULT 0, rows_added INTEGER NOT NULL DEFAULT 0, rows_skipped INTEGER NOT NULL DEFAULT 0, imported_by VARCHAR(64), created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS fin_statements (id SERIAL PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES fin_accounts(id), period_start DATE NOT NULL, period_end DATE NOT NULL, beginning_cents BIGINT NOT NULL, deposits_cents BIGINT NOT NULL, withdrawals_cents BIGINT NOT NULL, ending_cents BIGINT NOT NULL, source_file VARCHAR(200), batch_id INTEGER REFERENCES fin_import_batches(id));
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_statement_period ON fin_statements(account_id, period_start, period_end);
CREATE TABLE IF NOT EXISTS fin_transactions (id SERIAL PRIMARY KEY, import_key VARCHAR(64) NOT NULL UNIQUE, batch_id INTEGER NOT NULL REFERENCES fin_import_batches(id), account_id INTEGER NOT NULL REFERENCES fin_accounts(id), source_type VARCHAR(16) NOT NULL, source_txn_id VARCHAR(96), posted_date DATE NOT NULL, amount_cents BIGINT NOT NULL, description TEXT NOT NULL, source_file VARCHAR(200), source_page INTEGER, statement_period VARCHAR(64), source_category VARCHAR(96), source_issue VARCHAR(200), report_group VARCHAR(24) NOT NULL DEFAULT 'unclassified', category VARCHAR(64) NOT NULL DEFAULT 'Unclassified', designation VARCHAR(16) NOT NULL DEFAULT 'unknown', division VARCHAR(16) NOT NULL DEFAULT 'unassigned', confidence VARCHAR(16) NOT NULL DEFAULT 'review', needs_review BOOLEAN NOT NULL DEFAULT FALSE, review_reason VARCHAR(200), duplicate_status VARCHAR(20) NOT NULL DEFAULT 'unique', duplicate_of_id INTEGER REFERENCES fin_transactions(id), transfer_status VARCHAR(20) NOT NULL DEFAULT 'none', transfer_match_id INTEGER REFERENCES fin_transactions(id), verification_status VARCHAR(24) NOT NULL DEFAULT 'unverified', locked BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_fin_txn_date ON fin_transactions(posted_date);
CREATE INDEX IF NOT EXISTS ix_fin_txn_account_date ON fin_transactions(account_id, posted_date);
CREATE INDEX IF NOT EXISTS ix_fin_txn_review ON fin_transactions(needs_review);
CREATE TABLE IF NOT EXISTS fin_rules (id SERIAL PRIMARY KEY, pattern VARCHAR(200) NOT NULL UNIQUE, report_group VARCHAR(24) NOT NULL, category VARCHAR(64) NOT NULL, designation VARCHAR(16) NOT NULL DEFAULT 'business', division VARCHAR(16) NOT NULL DEFAULT 'unassigned', needs_review BOOLEAN NOT NULL DEFAULT FALSE, note VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS fin_reviews (id SERIAL PRIMARY KEY, transaction_id INTEGER NOT NULL REFERENCES fin_transactions(id), actor VARCHAR(64) NOT NULL, action VARCHAR(32) NOT NULL, before_value TEXT, after_value TEXT, note TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_fin_reviews_transaction_id ON fin_reviews(transaction_id);
CREATE TABLE IF NOT EXISTS fin_audit (id SERIAL PRIMARY KEY, actor VARCHAR(64), action VARCHAR(48) NOT NULL, detail VARCHAR(300), ip VARCHAR(64), allowed BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_fin_audit_created_at ON fin_audit(created_at);
COMMIT;
